			etag, err := conditionalmiddleware.GenerateETag(current)
			if err != nil {
				return err
			}
			if !conditionalmiddleware.MatchesIfMatch(ifMatch, etag) {
				return &UserMutationError{status: http.StatusPreconditionFailed, err: fmt.Errorf("precondition failed"), etag: etag}
			}
			return nil
